struct Poly {
    vector<pair<int,int>> cells;
    int w, h;
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if(!(cin>>n)) return 0;
    vector<Poly> polys(n);
    for(int i=0;i<n;i++){
        int k; cin>>k;
        polys[i].cells.resize(k);
        int minx=INT_MAX, miny=INT_MAX, maxx=INT_MIN, maxy=INT_MIN;
        for(int j=0;j<k;j++){
            int x,y; cin>>x>>y;
            polys[i].cells[j]={x,y};
            minx=min(minx,x);
            miny=min(miny,y);
            maxx=max(maxx,x);
            maxy=max(maxy,y);
        }
        polys[i].w = maxx - minx + 1;
        polys[i].h = maxy - miny + 1;
    }
    int totalW=0, maxH=0;
    for(auto &p:polys){
        totalW+=p.w;
        maxH=max(maxH,p.h);
    }
    cout<<totalW<<" "<<maxH<<"\n";
    int curX=0;
    for(int i=0;i<n;i++){
        // translation to curX, 0
        cout<<curX<<" "<<0<<" 0 0\n";
        curX+=polys[i].w;
    }
    return 0;
}
